    fn config_without_extends_still_works() {
        let temp = TempDir::new().unwrap();
        let bivvy_dir = temp.path().join(".bivvy");
        fs::create_dir_all(&bivvy_dir).unwrap();
        fs::write(bivvy_dir.join("config.yml"), "app_name: NoExtends").unwrap();

        // Using default resolver — won't make any HTTP calls
        let config = load_merged_config(temp.path()).unwrap();
        assert_eq!(config.app_name, Some("NoExtends".to_string()));
    }

    // --- TOML configuration support tests ---

    #[test]
    fn detect_format_returns_toml_for_toml_extension() {
        assert_eq!(
            ConfigFormat::detect(Path::new("config.toml")),
            ConfigFormat::Toml
        );
    }

    #[test]
    fn detect_format_returns_yaml_for_yml_extension() {
        assert_eq!(
            ConfigFormat::detect(Path::new("config.yml")),
            ConfigFormat::Yaml
        );
    }

    #[test]
    fn detect_format_defaults_to_yaml() {
        assert_eq!(
            ConfigFormat::detect(Path::new("config.json")),
            ConfigFormat::Yaml
        );
    }

