/// Find a config file by base name, preferring `.toml` over `.yml`.
///
/// Checks for `{base}.toml` first, then `{base}.yml`. Returns the
/// first path that exists.
fn find_config_file(dir: &Path, base: &str) -> Option<PathBuf> {
    let toml_path = dir.join(format!("{base}.toml"));
