    fn load_config_value_parses_toml() {
        let temp = TempDir::new().unwrap();
        let config_path = temp.path().join("config.toml");
        fs::write(&config_path, "key = \"value\"\n\n[nested]\ninner = 42").unwrap();

        let value = load_config_value(&config_path).unwrap();
        assert_eq!(value["key"], "value");
        assert_eq!(value["nested"]["inner"], 42);
    }

    #[test]
    fn discover_finds_toml_project_config() {
        let temp = TempDir::new().unwrap();
        let bivvy_dir = temp.path().join(".bivvy");
        fs::create_dir_all(&bivvy_dir).unwrap();
        fs::write(bivvy_dir.join("config.toml"), "app_name = \"test\"").unwrap();

        let paths = ConfigPaths::discover(temp.path());
        assert!(paths.project.is_some());
        assert!(paths.has_project_config());
        assert!(paths.project.unwrap().ends_with("config.toml"));
    }

    #[test]
    fn discover_prefers_toml_over_yml() {
        let temp = TempDir::new().unwrap();
        let bivvy_dir = temp.path().join(".bivvy");
        fs::create_dir_all(&bivvy_dir).unwrap();
        fs::write(bivvy_dir.join("config.yml"), "app_name: yaml").unwrap();
        fs::write(bivvy_dir.join("config.toml"), "app_name = \"toml\"").unwrap();

        let paths = ConfigPaths::discover(temp.path());
        assert!(paths.project.is_some());
        let project_path = paths.project.unwrap();
        assert!(project_path.ends_with("config.toml"));
    }

