///
/// Detects the format (YAML or TOML) from the file extension
/// and parses accordingly.
///
/// # Errors
///
/// Returns `ConfigNotFound` if the file doesn't exist.
/// Returns `ConfigParseError` if the content is invalid.
pub fn load_config_file(path: &Path) -> Result<BivvyConfig> {
    let content = read_config_content(path)?;
    parse_config(&content, path)
}

/// Parse config content into BivvyConfig.
///
/// Detects the format from the file extension: `.toml` files are
/// parsed as TOML, everything else as YAML.
///
/// # Arguments
///
/// * `content` - The file content to parse
/// * `source_path` - Path used for format detection and error reporting
pub fn parse_config(content: &str, source_path: &Path) -> Result<BivvyConfig> {
    match ConfigFormat::detect(source_path) {
        ConfigFormat::Toml => {
            toml::from_str(content).map_err(|e| BivvyError::ConfigParseError {
                path: source_path.to_path_buf(),
                message: e.to_string(),
            })
        }
        ConfigFormat::Yaml => {
            serde_yaml::from_str(content).map_err(|e| BivvyError::ConfigParseError {
                path: source_path.to_path_buf(),
                message: e.to_string(),
            })
        }
    }
}

/// Load a config file as raw serde_yaml::Value (for merging).
///
/// Detects the format from the file extension. TOML files are parsed
/// and converted to serde_yaml::Value so the merger can treat all
/// formats uniformly.
pub fn load_config_value(path: &Path) -> Result<serde_yaml::Value> {
    let content = read_config_content(path)?;

    match ConfigFormat::detect(path) {
        ConfigFormat::Toml => {
            let toml_val: toml::Value =
                toml::from_str(&content).map_err(|e| BivvyError::ConfigParseError {
                    path: path.to_path_buf(),
                    message: e.to_string(),
                })?;
            serde_yaml::to_value(&toml_val).map_err(|e| BivvyError::ConfigParseError {
                path: path.to_path_buf(),
                message: format!("Failed to convert TOML to merge value: {e}"),
            })
        }
        ConfigFormat::Yaml => {
            serde_yaml::from_str(&content).map_err(|e| BivvyError::ConfigParseError {
                path: path.to_path_buf(),
                message: e.to_string(),
            })
        }
    }
}

